import{_ as a,o as t,c as n,ai as e}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"第三层 · 质量与安全保障","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality.md","filePath":"ai/productivity/dev-spec/03-quality.md"}'),i={name:"ai/productivity/dev-spec/03-quality.md"};function l(r,s,p,d,o,c){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="第三层-·-质量与安全保障" tabindex="-1">第三层 · 质量与安全保障 <a class="header-anchor" href="#第三层-·-质量与安全保障" aria-label="Permalink to “第三层 · 质量与安全保障”">​</a></h1><blockquote><p>确保结果可靠。这一层不是开发结束后才执行的收尾检查，而是从项目准备到最终交付<strong>全程贯穿</strong>的保障机制——每一轮改动都受它约束。</p></blockquote><h2 id="为什么贯穿全程" tabindex="-1">为什么贯穿全程 <a class="header-anchor" href="#为什么贯穿全程" aria-label="Permalink to “为什么贯穿全程”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>第三层在做什么</th></tr></thead><tbody><tr><td>项目准备</td><td>确认代码规范、禁改区、构建检查命令、生产资源标记</td></tr><tr><td>需求 / 架构</td><td>把质量要求写进验收标准和方案，数据变更先想回滚</td></tr><tr><td>开发</td><td>每轮改动做局部质量 + Git 检查</td></tr><tr><td>审查 / 修复 / 重构 / 测试</td><td>保证不引入新问题、不改行为、验证有证据</td></tr><tr><td>交付</td><td>四层验收、diff 全量检查、安全全项、遗留归零</td></tr></tbody></table><p>六项保障：<strong>代码质量 · 测试验证 · 数据安全 · Git 管理 · 变更控制 · 交付追踪回滚</strong>。</p><h2 id="_1-代码质量规范" tabindex="-1">1. 代码质量规范 <a class="header-anchor" href="#_1-代码质量规范" aria-label="Permalink to “1. 代码质量规范”">​</a></h2><p><strong>审查清单</strong>：逻辑与业务规则完整性、边界条件（空值/零值/重复/越权）；异常不被吞、事务边界合理、失败不留半状态；接口/字段/返回结构变化已确认；测试覆盖关键与失败路径、断言没被放宽；改动范围无无关格式化、未用 import、调试打印、注释分支、遗留 TODO；命名分层符合现有风格。</p><p><strong>硬红线</strong>（命中必须处理）：硬编码绕过、吞异常、放宽断言/删用例、给数据加特判、越界改动或触碰禁改区。</p><p>让 AI 自查时明确「只输出问题清单和依据，不修改、不宣布通过」，每条指到 <code>文件:行号</code>。能脚本化的检查（构建、lint、密钥扫描、禁改区 diff）交给脚本（见第一层 Hooks）。</p><blockquote><p>提示词 · 代码质量自查</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对本轮改动做质量自查，只输出问题清单，不改文件、不宣布通过。改动：&lt;diff&gt;　约定：范围/禁改区/规范。</span></span>
<span class="line"><span>逐项查：逻辑与边界、异常与事务、兼容性、测试与断言、改动范围里的调试代码、可读性与重复。</span></span>
<span class="line"><span>每条给「文件:行号 | 问题 | 依据 | 建议改法」，单独列出硬红线命中项。没问题也逐项写「已检查，无问题」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_2-测试与验证规范" tabindex="-1">2. 测试与验证规范 <a class="header-anchor" href="#_2-测试与验证规范" aria-label="Permalink to “2. 测试与验证规范”">​</a></h2><p><strong>四态纪律</strong>：已验证（实际执行 + 输出证据）、未验证（说明原因 + 替代检查）、受限（环境权限不允许）、不适用（本次不涉及）。<strong>不能执行的测试不得写成通过，没有输出的「已测试」等于没测试。</strong></p><table tabindex="0"><thead><tr><th>项</th><th>合格证据</th><th>不合格写法</th></tr></thead><tbody><tr><td>编译</td><td>命令原文 + 成功输出</td><td>「编译通过」</td></tr><tr><td>单测</td><td>命令原文 + 通过/失败数</td><td>「测试都过了」</td></tr><tr><td>接口冒烟</td><td>请求与返回原文</td><td>「接口正常」</td></tr></tbody></table><p><strong>回归三层次</strong>：同模块（共用方法/DTO/同张表）、上下游（调用方/消息消费方）、全局（权限/租户/状态机/事务）。做对照表，至少留一条「改前行为保持」的证据——只验证「修好了什么」不验证「没改坏什么」不算完整。</p><blockquote><p>提示词 · 验证结果真实性自查</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>检查这份「已完成」报告里有没有把未验证写成通过，本轮只检查。报告：&lt;粘贴&gt;</span></span>
<span class="line"><span>检查：1 每条「通过」是否附命令和输出证据 2 是否把未跑/受限/不适用写成通过 3 回归是否含「已修复」和「改前行为保持」4 有无编造的测试输出。</span></span>
<span class="line"><span>输出可疑条目清单（原文 + 为什么可疑 + 需补什么证据）。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_3-数据与安全规范" tabindex="-1">3. 数据与安全规范 <a class="header-anchor" href="#_3-数据与安全规范" aria-label="Permalink to “3. 数据与安全规范”">​</a></h2><p><strong>敏感信息</strong>：密钥、令牌、密码、手机号、身份证号不写进代码/配置/日志/提交信息；<code>.env</code>、凭证不进版本库；日志不打印完整请求体、隐私、认证头；提交前跑密钥扫描。</p><p><strong>破坏性操作</strong>（命中即停、需人确认）：删数据、清库、改生产配置、不可逆迁移；脚本写死生产地址或高权限账号；覆盖用户改动、强推、删分支；批量删除或格式化无关目录。能只读不写、能连测试库不连生产、能限定目录不开放全盘。</p><p><strong>输入与权限</strong>：外部入参校验（类型/长度/格式/范围）；越权拦截（数据范围/租户/角色）；文件上传、路径/SQL/命令拼接风险；幂等与重复执行（接口重试、消息重复消费不出错数据）。</p><p><strong>依赖</strong>：不新增来源不明的依赖或脚本，版本锁定，核心依赖需方案确认。</p><blockquote><p>提示词 · 交付前安全检查</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对本次改动做安全自查，只输出检查结果，不修改。改动：&lt;diff&gt;</span></span>
<span class="line"><span>四块：1 敏感信息（密钥/隐私/凭证文件/日志打印）2 破坏性操作（删数据/清库/生产配置/写死生产资源）3 输入与权限（入参校验/越权/拼接/幂等）4 依赖（未知依赖/版本锁定）。</span></span>
<span class="line"><span>每项给「已检查/未检查/不适用」+依据，命中红线的单列并标「需人确认」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_4-git-与版本管理" tabindex="-1">4. Git 与版本管理 <a class="header-anchor" href="#_4-git-与版本管理" aria-label="Permalink to “4. Git 与版本管理”">​</a></h2><p><strong>提交前硬规矩</strong>：</p><ul><li>先看 <code>git status</code>，识别用户已有的改动、未跟踪文件、暂存区内容。</li><li><strong>不覆盖用户已有改动</strong>：同文件既有用户改动又有 AI 改动时停下说明，不擅自 <code>checkout --</code>、<code>reset --hard</code>、<code>stash</code>、强推或强行合并。</li><li>判断不了某处改动是谁改的，停下来问，不猜。</li><li>改动都在允许范围、没碰禁改区和依赖文件；不擅自 push、合并、删分支。</li></ul><p><strong>diff 检查</strong>：无批量格式化无关文件、依赖文件无意外变更、无硬编码/吞异常/放宽断言、无删除或注释掉现有测试、无调试打印/遗留 TODO，提交信息说清「改了什么、为什么」而非「update/fix」。一个提交对应一个能独立验收的子任务。</p><blockquote><p>提示词 · 提交前 Git 安全检查</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对当前工作区做提交前检查，只输出检查结果，不执行任何 git 写操作（不 add/commit/checkout/reset/stash/push）。</span></span>
<span class="line"><span>先读 git status、git diff、git diff --cached、最近 log。</span></span>
<span class="line"><span>检查：1 用户已有改动/未跟踪/暂存内容与本次是否混在一起 2 改动是否在范围、是否触禁改区和依赖 3 diff 里有无硬编码/吞异常/放宽断言/删测试/调试打印/格式化 4 提交信息是否说清改了什么为什么。</span></span>
<span class="line"><span>输出：可安全提交清单 + 需人确认的冲突疑点 + 建议的提交拆分。不要替我判断性合并。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_5-变更控制" tabindex="-1">5. 变更控制 <a class="header-anchor" href="#_5-变更控制" aria-label="Permalink to “5. 变更控制”">​</a></h2><p><strong>修改范围三栏</strong>（每次任务都写，落到具体路径）：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>允许修改：&lt;文件路径&gt;</span></span>
<span class="line"><span>禁止修改：&lt;接口签名 / 历史目录 / 依赖文件&gt;</span></span>
<span class="line"><span>必须保持兼容：&lt;返回结构 / 状态机规则&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>AI 说「顺手把…也改了」、开始改依赖或公共模块，立即停。</p><p><strong>检查点</strong>：方案预先约定哪些是检查点（契约冻结后、数据层改完、接口联调前），到点必须停下等人确认，不自行通过。人只回答：选哪个方案、加哪些边界、哪些风险不接受。</p><p><strong>失败分类</strong>：代码错误可重试有限轮次；环境问题标受限写替代检查；认知问题（改 A 坏 B）停手回分析；需求冲突交人确认。不一律重试。</p><p><strong>遗留文件清理</strong>：交付前清理本次产生的临时文件（.bak/.tmp/~）、一次性调试脚本、临时日志、注释掉的旧代码、遗留 TODO、不该进版本库的构建产物。<strong>只删这次任务产生的，判断不了归属就问。</strong></p><blockquote><p>提示词 · 变更范围检查</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>检查本次改动是否超出约定范围，只输出检查结果，不修改。</span></span>
<span class="line"><span>三栏（粘贴）：允许修改 / 禁止修改 / 必须保持兼容。当前 status 和 diff（粘贴）。</span></span>
<span class="line"><span>逐项查：实际改动是否都在允许内、是否触碰禁止、有无意外改动（依赖/公共模块/无关格式化）、必须兼容的内容是否真没变。</span></span>
<span class="line"><span>输出：合规清单 + 越界项（文件:行号）+ 需人确认疑点。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_6-交付追踪与回滚" tabindex="-1">6. 交付追踪与回滚 <a class="header-anchor" href="#_6-交付追踪与回滚" aria-label="Permalink to “6. 交付追踪与回滚”">​</a></h2><p><strong>交付追踪</strong>：报告留痕，最少含任务/级别/范围/不做项执行情况、修改文件（改了什么+为什么）、验证证据（命令+输出）、安全结论、遗留问题（是什么+影响+建议+谁决定）、沉淀去向。遗留必须有去处（建待办/写认知资料/报告留痕有人负责），「下次再说」不算处理。</p><p><strong>回滚方案</strong>：复杂改动（数据结构、接口契约、多文件、迁移）在方案阶段就写好：</p><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>触发条件</td><td>什么情况必须回滚</td></tr><tr><td>粒度</td><td>按哪个提交/阶段回退</td></tr><tr><td>数据回滚</td><td>迁移能否逆执行、数据能否恢复</td></tr><tr><td>兼容兜底</td><td>新旧能否并存、是否需开关</td></tr><tr><td>回滚后验证</td><td>回到什么状态算成功</td></tr></tbody></table><p>出问题先复现固定证据 → 判断前滚修复还是回滚（看改动范围、数据影响、时间成本）→ 按方案执行并保护未涉及改动 → 回滚后验证 → 在报告记录。</p><blockquote><p>提示词 · 生成回滚方案</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>为本次改动生成回滚方案，本轮只输出方案不执行。改动：&lt;描述&gt;　范围：&lt;文件/接口/数据表/迁移&gt;</span></span>
<span class="line"><span>输出：1 触发条件 2 回滚粒度（列相关提交）3 数据回滚（可逆性/恢复/丢失风险）4 兼容兜底 5 回滚步骤（标出需人确认的操作）6 回滚后验证。</span></span>
<span class="line"><span>无法回滚的部分明确标出并给替代处理（如只能前滚）。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="交付前总检查清单" tabindex="-1">交付前总检查清单 <a class="header-anchor" href="#交付前总检查清单" aria-label="Permalink to “交付前总检查清单”">​</a></h2><p>打钩前逐条核对，任何一条不过就不算完成：</p><ul><li>[ ] <strong>质量</strong>：审查清单逐项过完，硬红线命中为零。</li><li>[ ] <strong>验证</strong>：每条通过都有命令和输出证据，四态分清，回归含「保持」证据。</li><li>[ ] <strong>安全</strong>：敏感信息、破坏性操作、输入权限、依赖四项有明确结论。</li><li>[ ] <strong>Git</strong>：用户已有改动完整保留，无擅自 checkout/reset/stash/push，diff 干净。</li><li>[ ] <strong>变更</strong>：改动都在范围内，检查点未被跳过，遗留文件已清理（无误删用户文件）。</li><li>[ ] <strong>追踪</strong>：报告完整，遗留有去处有人负责，复杂改动有回滚方案。</li></ul><p>回到 <a href="/my-vitepress-site/ai/productivity/dev-spec/">总览</a> · 上一层 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle.html">第二层 · 软件开发生命周期</a>。</p>`,51)])])}const g=a(i,[["render",l]]);export{b as __pageData,g as default};
